INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CI001', 'HDSAT-RW-M18-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Sleep deprivation, also known as sleep insufficiency or sleeplessness, is the health condition of not having adequate duration or quality of sleep to support proper alertness, performance, and health. It can be either chronic or acute and may vary widely in severity. This means it can occur over both short and long periods. Sleep is important because adequate sleep, or restful sleep, is essential for maintaining overall health, brain performance, emotional regulation, and metabolic balance. Persistent sleep insufficiency can contribute to cognitive decline, emotional instability, and biological wear that has effects similar to accelerated aging. Scientific research demonstrates that inadequate sleep produces chronic consequences for overall health, ranging from attentional lapses to long-term neurodegenerative changes. The human body and most living organisms depend on sleep for neural recovery. All known animals sleep or exhibit some form of sleep behavior, and the importance of sleep is self-evident for humans, as nearly a third of a person''s life is spent sleeping. Sleep deprivation is common, affecting about one-third of the population. The US National Sleep Foundation recommends that adults aim for 7 hours of sleep per night. Children and teenagers require even more sleep, ranging from 8–16 hours per night. For healthy young individuals with normal sleep, the appropriate sleep duration for school-aged children is between 9 and 11 hours.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Adults need less sleep than children, so sleep deprivation is most common among the elderly."}, {"id": "B", "text": "Sleep loss has no measurable effect on brain performance or emotional regulation."}, {"id": "C", "text": "Sleep deprivation is a rare condition that mainly affects older adults."}, {"id": "D", "text": "Sleep deprivation harms alertness, performance and long-term health, and it affects a large share of the population."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Sleep deprivation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Sleep_deprivation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CI001', 'D', ARRAY['D']::TEXT[], 'The passage defines sleep deprivation, stresses sleep''s role in health and brain performance, lists consequences of insufficient sleep, and notes that about one-third of people are affected.', '{"C": "The text says sleep deprivation affects about one-third of the population and can occur at any age.", "A": "The text says children and teenagers require more sleep than adults, not that adults need less than the elderly.", "B": "The text says inadequate sleep produces consequences ranging from attentional lapses to long-term neurodegenerative changes."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-INF001', 'HDSAT-RW-M18-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Sleep deprivation, also known as sleep insufficiency or sleeplessness, is the health condition of not having adequate duration or quality of sleep to support proper alertness, performance, and health. It can be either chronic or acute and may vary widely in severity. This means it can occur over both short and long periods. Sleep is important because adequate sleep, or restful sleep, is essential for maintaining overall health, brain performance, emotional regulation, and metabolic balance. Persistent sleep insufficiency can contribute to cognitive decline, emotional instability, and biological wear that has effects similar to accelerated aging. Scientific research demonstrates that inadequate sleep produces chronic consequences for overall health, ranging from attentional lapses to long-term neurodegenerative changes. The human body and most living organisms depend on sleep for neural recovery. All known animals sleep or exhibit some form of sleep behavior, and the importance of sleep is self-evident for humans, as nearly a third of a person''s life is spent sleeping. Sleep deprivation is common, affecting about one-third of the population. The US National Sleep Foundation recommends that adults aim for 7 hours of sleep per night. Children and teenagers require even more sleep, ranging from 8–16 hours per night. For healthy young individuals with normal sleep, the appropriate sleep duration for school-aged children is between 9 and 11 hours.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-INF001', 'A', ARRAY['A']::TEXT[], 'The passage presents chronic sleep loss as producing lasting cognitive and biological harm, which supports treating it as a long-term health risk.', '{"C": "The text links persistent insufficiency to biological wear resembling accelerated aging, which contradicts the idea that duration is irrelevant.", "B": "The National Sleep Foundation recommends adults aim for seven hours, not fewer.", "D": "The text emphasizes persistent insufficiency and chronic consequences, so ignoring chronic patterns would be the opposite of its implication."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-TS001', 'HDSAT-RW-M18-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Sleep deprivation, also known as sleep insufficiency or sleeplessness, is the health condition of not having adequate duration or quality of sleep to support proper alertness, performance, and health. It can be either chronic or acute and may vary widely in severity. This means it can occur over both short and long periods. Sleep is important because adequate sleep, or restful sleep, is essential for maintaining overall health, brain performance, emotional regulation, and metabolic balance. Persistent sleep insufficiency can contribute to cognitive decline, emotional instability, and biological wear that has effects similar to accelerated aging. Scientific research demonstrates that inadequate sleep produces chronic consequences for overall health, ranging from attentional lapses to long-term neurodegenerative changes. The human body and most living organisms depend on sleep for neural recovery. All known animals sleep or exhibit some form of sleep behavior, and the importance of sleep is self-evident for humans, as nearly a third of a person''s life is spent sleeping. Sleep deprivation is common, affecting about one-third of the population. The US National Sleep Foundation recommends that adults aim for 7 hours of sleep per night. Children and teenagers require even more sleep, ranging from 8–16 hours per night. For healthy young individuals with normal sleep, the appropriate sleep duration for school-aged children is between 9 and 11 hours.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines sleep deprivation, explains why sleep matters, describes its consequences and prevalence, and gives recommended durations."}, {"id": "B", "text": "It traces the history of sleep research from ancient times to the present."}, {"id": "C", "text": "It compares two competing theories of why animals sleep."}, {"id": "D", "text": "It argues that sleep deprivation is not a serious public health concern."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Sleep deprivation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Sleep_deprivation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-TS001', 'A', ARRAY['A']::TEXT[], 'The text moves from definition to the importance of sleep, then to consequences, prevalence and recommended sleep durations.', '{"B": "The text makes no historical claims about sleep research.", "C": "The text asserts that all known animals sleep but does not compare theories.", "D": "The text describes serious consequences and widespread prevalence rather than dismissing the concern."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CE001', 'HDSAT-RW-M18-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Easy', 'multiple_choice', 'Sleep deprivation, also known as sleep insufficiency or sleeplessness, is the health condition of not having adequate duration or quality of sleep to support proper alertness, performance, and health. It can be either chronic or acute and may vary widely in severity. This means it can occur over both short and long periods. Sleep is important because adequate sleep, or restful sleep, is essential for maintaining overall health, brain performance, emotional regulation, and metabolic balance. Persistent sleep insufficiency can contribute to cognitive decline, emotional instability, and biological wear that has effects similar to accelerated aging. Scientific research demonstrates that inadequate sleep produces chronic consequences for overall health, ranging from attentional lapses to long-term neurodegenerative changes. The human body and most living organisms depend on sleep for neural recovery. All known animals sleep or exhibit some form of sleep behavior, and the importance of sleep is self-evident for humans, as nearly a third of a person''s life is spent sleeping. Sleep deprivation is common, affecting about one-third of the population. The US National Sleep Foundation recommends that adults aim for 7 hours of sleep per night. Children and teenagers require even more sleep, ranging from 8–16 hours per night. For healthy young individuals with normal sleep, the appropriate sleep duration for school-aged children is between 9 and 11 hours.', 'Which quotation from the text most directly supports the claim that sleep deprivation is widespread?', '[{"id": "A", "text": "All known animals sleep or exhibit some form of sleep behavior."}, {"id": "B", "text": "It can be either chronic or acute and may vary widely in severity."}, {"id": "C", "text": "Sleep deprivation is common, affecting about one-third of the population."}, {"id": "D", "text": "The US National Sleep Foundation recommends that adults aim for 7 hours of sleep per night."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Sleep deprivation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Sleep_deprivation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CE001', 'C', ARRAY['C']::TEXT[], 'Only the correct quotation states a proportion of the population affected by sleep deprivation.', '{"B": "This sentence describes the course and severity of sleep deprivation, not how common it is.", "A": "This sentence concerns animals generally, not the share of people affected.", "D": "This sentence gives a recommendation rather than a prevalence figure."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CI002', 'HDSAT-RW-M18-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A circadian rhythm (), or circadian cycle, is a natural oscillation that repeats roughly every 24 hours. Circadian rhythms can refer to any process that originates within an organism (i.e., endogenous) and responds to the environment (is entrained by the environment). Circadian rhythms are regulated by a circadian clock whose primary function is to rhythmically co-ordinate biological processes so they occur at the correct time to maximize the fitness of an individual. Circadian rhythms have been widely observed in animals, plants, fungi and cyanobacteria and there is evidence that they evolved independently in each of these kingdoms of life. The term circadian comes from the Latin circa, meaning "around", and dies, meaning "day". Processes with 24-hour cycles are more generally called diurnal rhythms; diurnal rhythms should not be called circadian rhythms unless they can be confirmed as endogenous, and not environmental. Although circadian rhythms are endogenous, they are adjusted to the local environment by external cues called zeitgebers (from German Zeitgeber (German: [ˈtsaɪtˌɡeːbɐ]; lit. ''time giver'')), which include light, temperature and redox cycles. In clinical settings, an abnormal circadian rhythm in humans is known as a circadian rhythm sleep disorder.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Circadian rhythms are daily patterns caused entirely by changes in sunlight."}, {"id": "B", "text": "Circadian rhythms occur only in humans and other mammals."}, {"id": "C", "text": "Circadian rhythms are internal roughly 24-hour cycles found across many forms of life that are adjusted by external cues."}, {"id": "D", "text": "Circadian rhythms are learned behaviors that animals acquire from their environments."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Circadian rhythm", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Circadian_rhythm', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CI002', 'C', ARRAY['C']::TEXT[], 'The passage defines circadian rhythms as internal ~24-hour oscillations regulated by a circadian clock, notes their wide distribution and independent evolution, and explains how zeitgebers adjust them.', '{"A": "The text says circadian rhythms are endogenous and should not be called circadian unless confirmed as internal.", "B": "The text says they have been observed in animals, plants, fungi and cyanobacteria.", "D": "The text describes them as natural oscillations originating within organisms, not learned behaviors."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-INF002', 'HDSAT-RW-M18-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'A circadian rhythm (), or circadian cycle, is a natural oscillation that repeats roughly every 24 hours. Circadian rhythms can refer to any process that originates within an organism (i.e., endogenous) and responds to the environment (is entrained by the environment). Circadian rhythms are regulated by a circadian clock whose primary function is to rhythmically co-ordinate biological processes so they occur at the correct time to maximize the fitness of an individual. Circadian rhythms have been widely observed in animals, plants, fungi and cyanobacteria and there is evidence that they evolved independently in each of these kingdoms of life. The term circadian comes from the Latin circa, meaning "around", and dies, meaning "day". Processes with 24-hour cycles are more generally called diurnal rhythms; diurnal rhythms should not be called circadian rhythms unless they can be confirmed as endogenous, and not environmental. Although circadian rhythms are endogenous, they are adjusted to the local environment by external cues called zeitgebers (from German Zeitgeber (German: [ˈtsaɪtˌɡeːbɐ]; lit. ''time giver'')), which include light, temperature and redox cycles. In clinical settings, an abnormal circadian rhythm in humans is known as a circadian rhythm sleep disorder.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-INF002', 'A', ARRAY['A']::TEXT[], 'The text says diurnal rhythms should not be called circadian unless confirmed as endogenous, so a pattern driven only by light is diurnal, not circadian.', '{"D": "The text distinguishes circadian from diurnal precisely on the question of internal origin, and a purely light-driven pattern has no internal clock.", "B": "A zeitgeber is the external cue itself, such as light, not the daily pattern it produces.", "C": "A light-driven pattern says nothing about whether the organism possesses a clock; it only says the pattern is not endogenous."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-TS002', 'HDSAT-RW-M18-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A circadian rhythm (), or circadian cycle, is a natural oscillation that repeats roughly every 24 hours. Circadian rhythms can refer to any process that originates within an organism (i.e., endogenous) and responds to the environment (is entrained by the environment). Circadian rhythms are regulated by a circadian clock whose primary function is to rhythmically co-ordinate biological processes so they occur at the correct time to maximize the fitness of an individual. Circadian rhythms have been widely observed in animals, plants, fungi and cyanobacteria and there is evidence that they evolved independently in each of these kingdoms of life. The term circadian comes from the Latin circa, meaning "around", and dies, meaning "day". Processes with 24-hour cycles are more generally called diurnal rhythms; diurnal rhythms should not be called circadian rhythms unless they can be confirmed as endogenous, and not environmental. Although circadian rhythms are endogenous, they are adjusted to the local environment by external cues called zeitgebers (from German Zeitgeber (German: [ˈtsaɪtˌɡeːbɐ]; lit. ''time giver'')), which include light, temperature and redox cycles. In clinical settings, an abnormal circadian rhythm in humans is known as a circadian rhythm sleep disorder.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that circadian rhythms are entirely environmental rather than internal."}, {"id": "B", "text": "It defines circadian rhythms, explains their regulation and distribution, traces the term''s origin, and distinguishes them from diurnal rhythms."}, {"id": "C", "text": "It presents a treatment for circadian rhythm sleep disorder."}, {"id": "D", "text": "It compares sleep patterns in humans with those of cyanobacteria."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Circadian rhythm", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Circadian_rhythm', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-TS002', 'B', ARRAY['B']::TEXT[], 'The text builds from definition to mechanism, distribution, etymology, the diurnal distinction and environmental adjustment.', '{"A": "The text says the rhythms are endogenous and only adjusted by the environment.", "D": "Cyanobacteria are mentioned only as one group in which circadian rhythms have been observed.", "C": "The disorder is named at the end but no treatment is described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CE002', 'HDSAT-RW-M18-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A circadian rhythm (), or circadian cycle, is a natural oscillation that repeats roughly every 24 hours. Circadian rhythms can refer to any process that originates within an organism (i.e., endogenous) and responds to the environment (is entrained by the environment). Circadian rhythms are regulated by a circadian clock whose primary function is to rhythmically co-ordinate biological processes so they occur at the correct time to maximize the fitness of an individual. Circadian rhythms have been widely observed in animals, plants, fungi and cyanobacteria and there is evidence that they evolved independently in each of these kingdoms of life. The term circadian comes from the Latin circa, meaning "around", and dies, meaning "day". Processes with 24-hour cycles are more generally called diurnal rhythms; diurnal rhythms should not be called circadian rhythms unless they can be confirmed as endogenous, and not environmental. Although circadian rhythms are endogenous, they are adjusted to the local environment by external cues called zeitgebers (from German Zeitgeber (German: [ˈtsaɪtˌɡeːbɐ]; lit. ''time giver'')), which include light, temperature and redox cycles. In clinical settings, an abnormal circadian rhythm in humans is known as a circadian rhythm sleep disorder.', 'Which quotation from the text most directly supports the claim that circadian rhythms are widespread across living things?', '[{"id": "A", "text": "In clinical settings, an abnormal circadian rhythm in humans is known as a circadian rhythm sleep disorder."}, {"id": "B", "text": "Circadian rhythms have been widely observed in animals, plants, fungi and cyanobacteria and there is evidence that they evolved independently in each of these kingdoms of life."}, {"id": "C", "text": "The term circadian comes from the Latin circa, meaning \"around\", and dies, meaning \"day\"."}, {"id": "D", "text": "A circadian rhythm (), or circadian cycle, is a natural oscillation that repeats roughly every 24 hours."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Circadian rhythm", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Circadian_rhythm', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CE002', 'B', ARRAY['B']::TEXT[], 'The correct quotation lists four broad groups of organisms and states that the rhythms evolved independently in each.', '{"C": "This sentence concerns the word''s etymology.", "A": "This sentence names a human disorder rather than the range of organisms affected.", "D": "This sentence gives a definition but does not show how widely the rhythms occur."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CI003', 'HDSAT-RW-M18-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Vaccination is the administration of a vaccine to help the immune system develop immunity from a disease. Vaccines contain a microorganism or virus in a weakened, live or killed state, or proteins or toxins from the organism. In stimulating the body''s adaptive immunity, they help prevent sickness from an infectious disease. When a sufficiently large percentage of a population has been vaccinated, herd immunity results. Herd immunity protects those who may be immunocompromised and cannot get a vaccine because even a weakened version would harm them. The effectiveness of vaccination has been widely studied and verified. Vaccination is the most effective method of preventing infectious diseases; widespread immunity due to vaccination is largely responsible for the worldwide eradication of smallpox and the elimination of diseases such as polio and tetanus from much of the world. According to the World Health Organization (WHO), vaccination prevents 3.5–5 million deaths per year. A WHO-funded study by The Lancet estimates that, during the 50-year period starting in 1974, vaccination prevented 154 million deaths, including 146 million among children under age 5. However, some diseases have seen rising cases due to relatively low vaccination rates attributable partly to vaccine hesitancy. The first disease people tried to prevent by inoculation was most likely smallpox, with the first recorded use of variolation occurring in the 16th century in China.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Vaccination works by injecting fully active pathogens that cause the disease."}, {"id": "B", "text": "Vaccination has eliminated smallpox, polio and tetanus worldwide."}, {"id": "C", "text": "Vaccination is effective only when every member of a population is immunized."}, {"id": "D", "text": "Vaccination trains the immune system to prevent disease and has saved millions of lives, though low vaccination rates allow some diseases to resurge."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Vaccination", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Vaccination', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CI003', 'D', ARRAY['D']::TEXT[], 'The passage explains how vaccines stimulate adaptive immunity, presents evidence of their effectiveness and impact, and notes that rising cases can follow low vaccination rates.', '{"A": "The text says vaccines contain weakened, live or killed organisms or their proteins or toxins.", "B": "The text says smallpox was eradicated worldwide, while polio and tetanus were eliminated from much of the world, not everywhere.", "C": "The text describes herd immunity as protection when a sufficiently large percentage is vaccinated, not all."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-INF003', 'HDSAT-RW-M18-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Vaccination is the administration of a vaccine to help the immune system develop immunity from a disease. Vaccines contain a microorganism or virus in a weakened, live or killed state, or proteins or toxins from the organism. In stimulating the body''s adaptive immunity, they help prevent sickness from an infectious disease. When a sufficiently large percentage of a population has been vaccinated, herd immunity results. Herd immunity protects those who may be immunocompromised and cannot get a vaccine because even a weakened version would harm them. The effectiveness of vaccination has been widely studied and verified. Vaccination is the most effective method of preventing infectious diseases; widespread immunity due to vaccination is largely responsible for the worldwide eradication of smallpox and the elimination of diseases such as polio and tetanus from much of the world. According to the World Health Organization (WHO), vaccination prevents 3.5–5 million deaths per year. A WHO-funded study by The Lancet estimates that, during the 50-year period starting in 1974, vaccination prevented 154 million deaths, including 146 million among children under age 5. However, some diseases have seen rising cases due to relatively low vaccination rates attributable partly to vaccine hesitancy. The first disease people tried to prevent by inoculation was most likely smallpox, with the first recorded use of variolation occurring in the 16th century in China.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-INF003', 'B', ARRAY['B']::TEXT[], 'The passage says herd immunity shields those who cannot be vaccinated. Without high vaccination coverage, that indirect protection weakens.', '{"D": "Herd immunity requires a sufficiently large percentage of immune people, so low rates work against it.", "C": "The text presents vaccination as the main route to the immunity that produces herd protection.", "A": "Newborns are described as too young to receive many vaccines, so they depend on the protection of others."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-TS003', 'HDSAT-RW-M18-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Vaccination is the administration of a vaccine to help the immune system develop immunity from a disease. Vaccines contain a microorganism or virus in a weakened, live or killed state, or proteins or toxins from the organism. In stimulating the body''s adaptive immunity, they help prevent sickness from an infectious disease. When a sufficiently large percentage of a population has been vaccinated, herd immunity results. Herd immunity protects those who may be immunocompromised and cannot get a vaccine because even a weakened version would harm them. The effectiveness of vaccination has been widely studied and verified. Vaccination is the most effective method of preventing infectious diseases; widespread immunity due to vaccination is largely responsible for the worldwide eradication of smallpox and the elimination of diseases such as polio and tetanus from much of the world. According to the World Health Organization (WHO), vaccination prevents 3.5–5 million deaths per year. A WHO-funded study by The Lancet estimates that, during the 50-year period starting in 1974, vaccination prevented 154 million deaths, including 146 million among children under age 5. However, some diseases have seen rising cases due to relatively low vaccination rates attributable partly to vaccine hesitancy. The first disease people tried to prevent by inoculation was most likely smallpox, with the first recorded use of variolation occurring in the 16th century in China.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It recounts the history of variolation before describing modern vaccines."}, {"id": "B", "text": "It argues that vaccine hesitancy has no effect on disease outbreaks."}, {"id": "C", "text": "It compares vaccination with antibiotics as treatments for infectious disease."}, {"id": "D", "text": "It defines vaccination and its mechanism, presents evidence of its effectiveness, and notes the problem of low vaccination rates."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Vaccination", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Vaccination', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-TS003', 'D', ARRAY['D']::TEXT[], 'The text opens with a definition and mechanism, reviews evidence of effectiveness and lives saved, and closes with the consequences of low vaccination rates.', '{"A": "The history of variolation appears only in the final sentence as a minor detail.", "C": "Antibiotics are not mentioned.", "B": "The text says rising cases are partly attributable to vaccine hesitancy."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CE003', 'HDSAT-RW-M18-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Vaccination is the administration of a vaccine to help the immune system develop immunity from a disease. Vaccines contain a microorganism or virus in a weakened, live or killed state, or proteins or toxins from the organism. In stimulating the body''s adaptive immunity, they help prevent sickness from an infectious disease. When a sufficiently large percentage of a population has been vaccinated, herd immunity results. Herd immunity protects those who may be immunocompromised and cannot get a vaccine because even a weakened version would harm them. The effectiveness of vaccination has been widely studied and verified. Vaccination is the most effective method of preventing infectious diseases; widespread immunity due to vaccination is largely responsible for the worldwide eradication of smallpox and the elimination of diseases such as polio and tetanus from much of the world. According to the World Health Organization (WHO), vaccination prevents 3.5–5 million deaths per year. A WHO-funded study by The Lancet estimates that, during the 50-year period starting in 1974, vaccination prevented 154 million deaths, including 146 million among children under age 5. However, some diseases have seen rising cases due to relatively low vaccination rates attributable partly to vaccine hesitancy. The first disease people tried to prevent by inoculation was most likely smallpox, with the first recorded use of variolation occurring in the 16th century in China.', 'Which quotation from the text most directly supports the claim that vaccination has prevented millions of deaths?', '[{"id": "A", "text": "Vaccination is the most effective method of preventing infectious diseases."}, {"id": "B", "text": "The first disease people tried to prevent by inoculation was most likely smallpox."}, {"id": "C", "text": "Vaccines contain a microorganism or virus in a weakened, live or killed state, or proteins or toxins from the organism."}, {"id": "D", "text": "According to the World Health Organization (WHO), vaccination prevents 3.5–5 million deaths per year."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Vaccination", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Vaccination', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CE003', 'D', ARRAY['D']::TEXT[], 'The correct quotation gives an explicit annual figure for deaths prevented by vaccination.', '{"C": "This sentence describes what vaccines contain, not their effect on mortality.", "A": "This sentence asserts effectiveness in general terms without giving a death figure.", "B": "This sentence concerns the history of inoculation, not deaths prevented."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CI004', 'HDSAT-RW-M18-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Herd immunity (also called herd effect, community immunity, population immunity, or mass immunity) is a form of indirect protection that applies only to contagious diseases. It occurs when a sufficient percentage of a population has become immune to an infection, whether through previous infections or vaccination, that the communicable pathogen cannot maintain itself in the population, its low incidence thereby reducing the likelihood of infection for individuals who lack immunity. Once the herd immunity has been reached, disease gradually disappears from a population and may result in eradication or permanent reduction of infections to zero if achieved worldwide. Herd immunity created via vaccination has contributed to the reduction of many diseases. == Effects == === Protection of those without immunity === Some individuals either cannot develop immunity after vaccination or for medical reasons cannot be vaccinated. Newborn infants are too young to receive many vaccines, either for safety reasons or because passive immunity renders the vaccine ineffective. Individuals who are immunodeficient due to HIV/AIDS, lymphoma, leukemia, bone marrow cancer, an impaired spleen, chemotherapy, or radiotherapy may have lost any immunity that they previously had, and vaccines may not be of any use for them because of their immunodeficiency. A portion of those vaccinated may not develop long-term immunity. Vaccine contraindications may prevent certain individuals from being vaccinated.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Herd immunity applies to all diseases, including noncontagious ones."}, {"id": "B", "text": "Herd immunity requires that every person in a population be immune."}, {"id": "C", "text": "Herd immunity is indirect protection that arises when enough people are immune, and it shields those who cannot be vaccinated."}, {"id": "D", "text": "Herd immunity is achieved only through previous infection, never through vaccination."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Herd immunity", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Herd_immunity', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CI004', 'C', ARRAY['C']::TEXT[], 'The passage defines herd immunity as indirect protection for contagious diseases, explains the threshold effect, and details who depends on it.', '{"A": "The text says herd immunity applies only to contagious diseases.", "B": "The text says a sufficient percentage must be immune, not everyone.", "D": "The text says immunity can come through previous infections or vaccination."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-INF004', 'HDSAT-RW-M18-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Herd immunity (also called herd effect, community immunity, population immunity, or mass immunity) is a form of indirect protection that applies only to contagious diseases. It occurs when a sufficient percentage of a population has become immune to an infection, whether through previous infections or vaccination, that the communicable pathogen cannot maintain itself in the population, its low incidence thereby reducing the likelihood of infection for individuals who lack immunity. Once the herd immunity has been reached, disease gradually disappears from a population and may result in eradication or permanent reduction of infections to zero if achieved worldwide. Herd immunity created via vaccination has contributed to the reduction of many diseases. == Effects == === Protection of those without immunity === Some individuals either cannot develop immunity after vaccination or for medical reasons cannot be vaccinated. Newborn infants are too young to receive many vaccines, either for safety reasons or because passive immunity renders the vaccine ineffective. Individuals who are immunodeficient due to HIV/AIDS, lymphoma, leukemia, bone marrow cancer, an impaired spleen, chemotherapy, or radiotherapy may have lost any immunity that they previously had, and vaccines may not be of any use for them because of their immunodeficiency. A portion of those vaccinated may not develop long-term immunity. Vaccine contraindications may prevent certain individuals from being vaccinated.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-INF004', 'B', ARRAY['B']::TEXT[], 'The passage explains that herd immunity protects those who lack immunity themselves, which means their safety depends on others being immune.', '{"C": "Their own symptoms cannot protect them from infection in the first place.", "A": "The text says vaccines may be of no use to some immunodeficient people or may be unsafe for them.", "D": "Waiting for worldwide elimination would leave them unprotected in the meantime."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-TS004', 'HDSAT-RW-M18-TS004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Herd immunity (also called herd effect, community immunity, population immunity, or mass immunity) is a form of indirect protection that applies only to contagious diseases. It occurs when a sufficient percentage of a population has become immune to an infection, whether through previous infections or vaccination, that the communicable pathogen cannot maintain itself in the population, its low incidence thereby reducing the likelihood of infection for individuals who lack immunity. Once the herd immunity has been reached, disease gradually disappears from a population and may result in eradication or permanent reduction of infections to zero if achieved worldwide. Herd immunity created via vaccination has contributed to the reduction of many diseases. == Effects == === Protection of those without immunity === Some individuals either cannot develop immunity after vaccination or for medical reasons cannot be vaccinated. Newborn infants are too young to receive many vaccines, either for safety reasons or because passive immunity renders the vaccine ineffective. Individuals who are immunodeficient due to HIV/AIDS, lymphoma, leukemia, bone marrow cancer, an impaired spleen, chemotherapy, or radiotherapy may have lost any immunity that they previously had, and vaccines may not be of any use for them because of their immunodeficiency. A portion of those vaccinated may not develop long-term immunity. Vaccine contraindications may prevent certain individuals from being vaccinated.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares herd immunity with the mechanism of a vaccine."}, {"id": "B", "text": "It defines herd immunity and its effect, then explains how it protects people who lack immunity."}, {"id": "C", "text": "It argues that herd immunity cannot reduce disease incidence."}, {"id": "D", "text": "It traces the history of vaccination from the 16th century to the present."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Herd immunity", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Herd_immunity', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-TS004', 'B', ARRAY['B']::TEXT[], 'The text first defines herd immunity and its population-level effect, then turns to the individuals it protects.', '{"D": "The text gives no historical account.", "A": "The text mentions vaccination as one route to immunity but does not compare mechanisms.", "C": "The text says herd immunity reduces the likelihood of infection and can make disease disappear."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CE004', 'HDSAT-RW-M18-CE004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Easy', 'multiple_choice', 'Herd immunity (also called herd effect, community immunity, population immunity, or mass immunity) is a form of indirect protection that applies only to contagious diseases. It occurs when a sufficient percentage of a population has become immune to an infection, whether through previous infections or vaccination, that the communicable pathogen cannot maintain itself in the population, its low incidence thereby reducing the likelihood of infection for individuals who lack immunity. Once the herd immunity has been reached, disease gradually disappears from a population and may result in eradication or permanent reduction of infections to zero if achieved worldwide. Herd immunity created via vaccination has contributed to the reduction of many diseases. == Effects == === Protection of those without immunity === Some individuals either cannot develop immunity after vaccination or for medical reasons cannot be vaccinated. Newborn infants are too young to receive many vaccines, either for safety reasons or because passive immunity renders the vaccine ineffective. Individuals who are immunodeficient due to HIV/AIDS, lymphoma, leukemia, bone marrow cancer, an impaired spleen, chemotherapy, or radiotherapy may have lost any immunity that they previously had, and vaccines may not be of any use for them because of their immunodeficiency. A portion of those vaccinated may not develop long-term immunity. Vaccine contraindications may prevent certain individuals from being vaccinated.', 'Which quotation from the text most directly supports the claim that some people cannot be vaccinated for medical reasons?', '[{"id": "A", "text": "Herd immunity created via vaccination has contributed to the reduction of many diseases."}, {"id": "B", "text": "Once the herd immunity has been reached, disease gradually disappears from a population."}, {"id": "C", "text": "Herd immunity (also called herd effect, community immunity, population immunity, or mass immunity) is a form of indirect protection that applies only to contagious diseases."}, {"id": "D", "text": "Some individuals either cannot develop immunity after vaccination or for medical reasons cannot be vaccinated."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Herd immunity", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Herd_immunity', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CE004', 'D', ARRAY['D']::TEXT[], 'Only the correct quotation states that medical reasons can prevent some individuals from being vaccinated.', '{"C": "This sentence defines herd immunity and its scope.", "B": "This sentence describes the population-level result of reaching the threshold.", "A": "This sentence credits vaccination with reducing many diseases."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CI005', 'HDSAT-RW-M18-CI005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A coral reef is an underwater ecosystem characterized by reef-building corals. Reefs are formed of colonies of coral polyps held together by calcium carbonate. Most coral reefs are built from stony corals, whose polyps cluster in groups. Coral belongs to the class Anthozoa in the animal phylum Cnidaria, which includes sea anemones and jellyfish. Unlike sea anemones, corals secrete hard carbonate exoskeletons that support and protect the coral. Most reefs grow best in warm, shallow, clear, sunny, and agitated water. Coral reefs first appeared 485 million years ago, at the dawn of the Early Ordovician, displacing the microbial and sponge reefs of the Cambrian. Sometimes called rainforests of the sea, shallow coral reefs form some of Earth''s most diverse ecosystems. They occupy less than 0.1% of the world''s ocean area, about half the area of France. Yet, they provide a home for at least 25% of all marine species, including fish, mollusks, worms, crustaceans, echinoderms, sponges, tunicates and other cnidarians. Coral reefs flourish in ocean waters that provide few nutrients. They are most commonly found at shallow depths in tropical waters, but deep water and cold water coral reefs exist on smaller scales in other areas. Shallow tropical coral reefs have declined by 50% since 1950, partly because they are sensitive to water conditions.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Coral reefs are diverse ecosystems built by coral colonies that cover little ocean area yet support a large share of marine species."}, {"id": "B", "text": "Coral reefs grow best in cold, deep and nutrient-rich water."}, {"id": "C", "text": "Coral reefs occupy about half of the world''s ocean area."}, {"id": "D", "text": "Coral reefs are built by sea anemones and jellyfish rather than by corals."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Coral reef", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Coral_reef', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CI005', 'A', ARRAY['A']::TEXT[], 'The passage defines coral reefs, describes their formation and habitat, and emphasizes the contrast between their small area and their outsized share of marine species.', '{"D": "The text says corals differ from sea anemones and that reefs are built by stony corals.", "C": "The text says they occupy less than 0.1% of ocean area, about half the area of France.", "B": "The text says most reefs grow best in warm, shallow, clear, sunny and agitated water."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-INF005', 'HDSAT-RW-M18-INF005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A coral reef is an underwater ecosystem characterized by reef-building corals. Reefs are formed of colonies of coral polyps held together by calcium carbonate. Most coral reefs are built from stony corals, whose polyps cluster in groups. Coral belongs to the class Anthozoa in the animal phylum Cnidaria, which includes sea anemones and jellyfish. Unlike sea anemones, corals secrete hard carbonate exoskeletons that support and protect the coral. Most reefs grow best in warm, shallow, clear, sunny, and agitated water. Coral reefs first appeared 485 million years ago, at the dawn of the Early Ordovician, displacing the microbial and sponge reefs of the Cambrian. Sometimes called rainforests of the sea, shallow coral reefs form some of Earth''s most diverse ecosystems. They occupy less than 0.1% of the world''s ocean area, about half the area of France. Yet, they provide a home for at least 25% of all marine species, including fish, mollusks, worms, crustaceans, echinoderms, sponges, tunicates and other cnidarians. Coral reefs flourish in ocean waters that provide few nutrients. They are most commonly found at shallow depths in tropical waters, but deep water and cold water coral reefs exist on smaller scales in other areas. Shallow tropical coral reefs have declined by 50% since 1950, partly because they are sensitive to water conditions.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-INF005', 'B', ARRAY['B']::TEXT[], 'The passage ties reef decline partly to sensitivity to water conditions, which implies that protection depends on keeping those conditions suitable.', '{"C": "The text notes that deep and cold water reefs exist only on smaller scales, and relocation is not proposed.", "A": "The text says coral reefs flourish in waters that provide few nutrients.", "D": "Sea anemones are described as relatives of corals, not as a substitute that would preserve reef ecosystems."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-TS005', 'HDSAT-RW-M18-TS005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A coral reef is an underwater ecosystem characterized by reef-building corals. Reefs are formed of colonies of coral polyps held together by calcium carbonate. Most coral reefs are built from stony corals, whose polyps cluster in groups. Coral belongs to the class Anthozoa in the animal phylum Cnidaria, which includes sea anemones and jellyfish. Unlike sea anemones, corals secrete hard carbonate exoskeletons that support and protect the coral. Most reefs grow best in warm, shallow, clear, sunny, and agitated water. Coral reefs first appeared 485 million years ago, at the dawn of the Early Ordovician, displacing the microbial and sponge reefs of the Cambrian. Sometimes called rainforests of the sea, shallow coral reefs form some of Earth''s most diverse ecosystems. They occupy less than 0.1% of the world''s ocean area, about half the area of France. Yet, they provide a home for at least 25% of all marine species, including fish, mollusks, worms, crustaceans, echinoderms, sponges, tunicates and other cnidarians. Coral reefs flourish in ocean waters that provide few nutrients. They are most commonly found at shallow depths in tropical waters, but deep water and cold water coral reefs exist on smaller scales in other areas. Shallow tropical coral reefs have declined by 50% since 1950, partly because they are sensitive to water conditions.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that coral reefs are less diverse than other marine ecosystems."}, {"id": "B", "text": "It defines coral reefs and their builders, describes where they grow and how diverse they are, and notes their recent decline."}, {"id": "C", "text": "It compares the age of coral reefs with the age of the Cambrian sponge reefs."}, {"id": "D", "text": "It explains how to construct an artificial coral reef."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Coral reef", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Coral_reef', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-TS005', 'B', ARRAY['B']::TEXT[], 'The text begins with definition and formation, moves to habitat and biodiversity, and closes with the 50 percent decline since 1950.', '{"C": "The text mentions that reefs displaced Cambrian sponge reefs but does not compare ages in detail.", "D": "No construction method is described.", "A": "The text calls shallow coral reefs some of Earth''s most diverse ecosystems."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CE005', 'HDSAT-RW-M18-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Hard', 'multiple_choice', 'A coral reef is an underwater ecosystem characterized by reef-building corals. Reefs are formed of colonies of coral polyps held together by calcium carbonate. Most coral reefs are built from stony corals, whose polyps cluster in groups. Coral belongs to the class Anthozoa in the animal phylum Cnidaria, which includes sea anemones and jellyfish. Unlike sea anemones, corals secrete hard carbonate exoskeletons that support and protect the coral. Most reefs grow best in warm, shallow, clear, sunny, and agitated water. Coral reefs first appeared 485 million years ago, at the dawn of the Early Ordovician, displacing the microbial and sponge reefs of the Cambrian. Sometimes called rainforests of the sea, shallow coral reefs form some of Earth''s most diverse ecosystems. They occupy less than 0.1% of the world''s ocean area, about half the area of France. Yet, they provide a home for at least 25% of all marine species, including fish, mollusks, worms, crustaceans, echinoderms, sponges, tunicates and other cnidarians. Coral reefs flourish in ocean waters that provide few nutrients. They are most commonly found at shallow depths in tropical waters, but deep water and cold water coral reefs exist on smaller scales in other areas. Shallow tropical coral reefs have declined by 50% since 1950, partly because they are sensitive to water conditions.', 'Which quotation from the text most directly supports the claim that coral reefs support far more species than their area would suggest?', '[{"id": "A", "text": "Most reefs grow best in warm, shallow, clear, sunny, and agitated water."}, {"id": "B", "text": "They occupy less than 0.1% of the world''s ocean area, about half the area of France. Yet, they provide a home for at least 25% of all marine species, including fish, mollusks, worms, crustaceans, echinoderms, sponges, tunicates and other cnidarians."}, {"id": "C", "text": "Coral reefs flourish in ocean waters that provide few nutrients."}, {"id": "D", "text": "Coral reefs first appeared 485 million years ago, at the dawn of the Early Ordovician, displacing the microbial and sponge reefs of the Cambrian."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Coral reef", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Coral_reef', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CE005', 'B', ARRAY['B']::TEXT[], 'The correct quotation sets a tiny share of ocean area against at least 25 percent of marine species, which is exactly the contrast the claim describes.', '{"A": "This sentence describes preferred conditions, not biodiversity.", "D": "This sentence gives the geological age of reefs.", "C": "This sentence describes nutrient levels rather than species counts."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CI006', 'HDSAT-RW-M18-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Ocean acidification is the ongoing decrease in the pH of the Earth''s ocean. Between 1950 and 2026, the average pH of the ocean surface fell from approximately 8.15 to 8.05. Carbon dioxide emissions from human activities are the primary cause of ocean acidification, with atmospheric carbon dioxide (CO2) levels exceeding 422 ppm (as of 2024). CO2 from the atmosphere is absorbed by the oceans. This chemical reaction produces carbonic acid (H2CO3) which dissociates into a bicarbonate ion (HCO−3) and a hydrogen ion (H+). The presence of free hydrogen ions (H+) lowers the pH of the ocean, increasing acidity (this does not mean that seawater is acidic yet; It is still alkaline, with a pH higher than 8). Marine calcifying organisms, such as mollusks and corals, are especially vulnerable because they rely on calcium carbonate to build shells and skeletons. A change in pH by 0.1 represents a 26% increase in hydrogen ion concentration in the world''s oceans (the pH scale is logarithmic, so a change of one in pH units is equivalent to a tenfold change in hydrogen ion concentration). Sea-surface pH and carbonate saturation states vary depending on ocean depth and location. Colder and higher latitude waters are capable of absorbing more CO2. This can cause acidity to rise, lowering the pH and carbonate saturation levels in these areas. Several other factors influence the atmosphere-ocean CO2 exchange, and thus local ocean acidification.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Ocean acidification affects only deep, cold water and leaves surface waters unchanged."}, {"id": "B", "text": "Ocean acidification is caused mainly by natural volcanic activity."}, {"id": "C", "text": "Ocean acidification is a measurable drop in seawater pH caused mainly by absorbed carbon dioxide, and it threatens organisms that build shells and skeletons."}, {"id": "D", "text": "Ocean acidification has made seawater acidic, with a pH below 7."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Ocean acidification", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Ocean_acidification', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CI006', 'C', ARRAY['C']::TEXT[], 'The passage defines ocean acidification by the falling pH, traces the chemistry of CO2 absorption, and identifies calcifying organisms as especially vulnerable.', '{"D": "The text says seawater is still alkaline, with a pH higher than 8.", "B": "The text names carbon dioxide emissions from human activities as the primary cause.", "A": "The text reports a measured fall in average surface pH and says colder, higher-latitude waters absorb more CO2, not that surface waters are unaffected."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-INF006', 'HDSAT-RW-M18-INF006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Ocean acidification is the ongoing decrease in the pH of the Earth''s ocean. Between 1950 and 2026, the average pH of the ocean surface fell from approximately 8.15 to 8.05. Carbon dioxide emissions from human activities are the primary cause of ocean acidification, with atmospheric carbon dioxide (CO2) levels exceeding 422 ppm (as of 2024). CO2 from the atmosphere is absorbed by the oceans. This chemical reaction produces carbonic acid (H2CO3) which dissociates into a bicarbonate ion (HCO−3) and a hydrogen ion (H+). The presence of free hydrogen ions (H+) lowers the pH of the ocean, increasing acidity (this does not mean that seawater is acidic yet; It is still alkaline, with a pH higher than 8). Marine calcifying organisms, such as mollusks and corals, are especially vulnerable because they rely on calcium carbonate to build shells and skeletons. A change in pH by 0.1 represents a 26% increase in hydrogen ion concentration in the world''s oceans (the pH scale is logarithmic, so a change of one in pH units is equivalent to a tenfold change in hydrogen ion concentration). Sea-surface pH and carbonate saturation states vary depending on ocean depth and location. Colder and higher latitude waters are capable of absorbing more CO2. This can cause acidity to rise, lowering the pH and carbonate saturation levels in these areas. Several other factors influence the atmosphere-ocean CO2 exchange, and thus local ocean acidification.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-INF006', 'A', ARRAY['A']::TEXT[], 'The logarithmic scale means a 0.1 drop is a 26 percent rise in hydrogen ions, which is substantial despite the small-looking number.', '{"C": "The text says a change of 0.1 in pH is a 26 percent increase in hydrogen ion concentration and calls calcifying organisms especially vulnerable.", "D": "The text says seawater remains alkaline with a pH higher than 8.", "B": "The drop results from absorbed CO2, so absorption has been increasing rather than decreasing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-TS006', 'HDSAT-RW-M18-TS006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Ocean acidification is the ongoing decrease in the pH of the Earth''s ocean. Between 1950 and 2026, the average pH of the ocean surface fell from approximately 8.15 to 8.05. Carbon dioxide emissions from human activities are the primary cause of ocean acidification, with atmospheric carbon dioxide (CO2) levels exceeding 422 ppm (as of 2024). CO2 from the atmosphere is absorbed by the oceans. This chemical reaction produces carbonic acid (H2CO3) which dissociates into a bicarbonate ion (HCO−3) and a hydrogen ion (H+). The presence of free hydrogen ions (H+) lowers the pH of the ocean, increasing acidity (this does not mean that seawater is acidic yet; It is still alkaline, with a pH higher than 8). Marine calcifying organisms, such as mollusks and corals, are especially vulnerable because they rely on calcium carbonate to build shells and skeletons. A change in pH by 0.1 represents a 26% increase in hydrogen ion concentration in the world''s oceans (the pH scale is logarithmic, so a change of one in pH units is equivalent to a tenfold change in hydrogen ion concentration). Sea-surface pH and carbonate saturation states vary depending on ocean depth and location. Colder and higher latitude waters are capable of absorbing more CO2. This can cause acidity to rise, lowering the pH and carbonate saturation levels in these areas. Several other factors influence the atmosphere-ocean CO2 exchange, and thus local ocean acidification.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that ocean acidification has been overstated by scientists."}, {"id": "B", "text": "It lists proposed laws for limiting carbon dioxide emissions."}, {"id": "C", "text": "It compares ocean acidification with freshwater acidification in lakes."}, {"id": "D", "text": "It describes the pH decline, explains its chemical cause, identifies vulnerable organisms, and notes regional variation."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Ocean acidification", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Ocean_acidification', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-TS006', 'D', ARRAY['D']::TEXT[], 'The text moves from the observed trend, to the chemistry, to biological consequences, to variation by depth and latitude.', '{"A": "The text presents the decline and its effects as established findings.", "C": "Freshwater systems are not discussed.", "B": "No legislation is proposed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CE006', 'HDSAT-RW-M18-CE006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Easy', 'multiple_choice', 'Ocean acidification is the ongoing decrease in the pH of the Earth''s ocean. Between 1950 and 2026, the average pH of the ocean surface fell from approximately 8.15 to 8.05. Carbon dioxide emissions from human activities are the primary cause of ocean acidification, with atmospheric carbon dioxide (CO2) levels exceeding 422 ppm (as of 2024). CO2 from the atmosphere is absorbed by the oceans. This chemical reaction produces carbonic acid (H2CO3) which dissociates into a bicarbonate ion (HCO−3) and a hydrogen ion (H+). The presence of free hydrogen ions (H+) lowers the pH of the ocean, increasing acidity (this does not mean that seawater is acidic yet; It is still alkaline, with a pH higher than 8). Marine calcifying organisms, such as mollusks and corals, are especially vulnerable because they rely on calcium carbonate to build shells and skeletons. A change in pH by 0.1 represents a 26% increase in hydrogen ion concentration in the world''s oceans (the pH scale is logarithmic, so a change of one in pH units is equivalent to a tenfold change in hydrogen ion concentration). Sea-surface pH and carbonate saturation states vary depending on ocean depth and location. Colder and higher latitude waters are capable of absorbing more CO2. This can cause acidity to rise, lowering the pH and carbonate saturation levels in these areas. Several other factors influence the atmosphere-ocean CO2 exchange, and thus local ocean acidification.', 'Which quotation from the text most directly supports the claim that ocean acidification endangers organisms that build shells and skeletons?', '[{"id": "A", "text": "Marine calcifying organisms, such as mollusks and corals, are especially vulnerable because they rely on calcium carbonate to build shells and skeletons."}, {"id": "B", "text": "Colder and higher latitude waters are capable of absorbing more CO2."}, {"id": "C", "text": "Between 1950 and 2026, the average pH of the ocean surface fell from approximately 8.15 to 8.05."}, {"id": "D", "text": "CO2 from the atmosphere is absorbed by the oceans."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Ocean acidification", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Ocean_acidification', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CE006', 'A', ARRAY['A']::TEXT[], 'Only the correct quotation links the chemistry to calcifying organisms and explains their reliance on calcium carbonate.', '{"C": "This sentence reports the pH trend but does not name organisms affected.", "D": "This sentence describes the transfer of CO2 into the ocean.", "B": "This sentence describes regional absorption differences."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CI007', 'HDSAT-RW-M18-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Public transport (also known as public transportation, public transit, mass transit, or simply transit) refers to forms of transport made available for use by the general public. Public transport systems typically operate on fixed routes and schedules and charge a standardized fare intended to cover operating costs, often supplemented by public funding where required. There is no universally fixed definition of which modes are included. While systems such as buses and railways are commonly cited, air travel is often excluded from general discussions of public transport due to its market-driven structure and competitive pricing. Common examples include city buses, trolleybuses, trams (or light rail), rapid transit systems, passenger trains, and ferries. Intercity public transport is primarily provided by airlines, coaches, and intercity rail, with high-speed rail networks under development in several regions. Most public transport services operate along fixed corridors with designated boarding points and published timetables, allowing for predictable operations and efficient use of infrastructure. High-frequency services often prioritize regular headways over exact departure times. However, many trips involve multimodal travel, such as walking or feeder bus services to access rail stations, highlighting the importance of network coordination and cost-effective planning.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Public transport is any form of transport available to the public, including private cars and air travel."}, {"id": "B", "text": "Public transport is shared, fixed-route service with standardized fares, and it includes many modes even though air travel is usually excluded."}, {"id": "C", "text": "Public transport fares are always set high enough to cover all operating costs without public funding."}, {"id": "D", "text": "Public transport operates without schedules or fixed routes."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Public transport", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Public_transport', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CI007', 'B', ARRAY['B']::TEXT[], 'The passage defines public transport, discusses which modes count, and describes the fixed routes, schedules and fares that characterize it.', '{"A": "The text says air travel is often excluded and describes fixed routes and schedules.", "D": "The text says systems typically operate on fixed routes and schedules.", "C": "The text says fares are often supplemented by public funding where required."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-INF007', 'HDSAT-RW-M18-INF007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Public transport (also known as public transportation, public transit, mass transit, or simply transit) refers to forms of transport made available for use by the general public. Public transport systems typically operate on fixed routes and schedules and charge a standardized fare intended to cover operating costs, often supplemented by public funding where required. There is no universally fixed definition of which modes are included. While systems such as buses and railways are commonly cited, air travel is often excluded from general discussions of public transport due to its market-driven structure and competitive pricing. Common examples include city buses, trolleybuses, trams (or light rail), rapid transit systems, passenger trains, and ferries. Intercity public transport is primarily provided by airlines, coaches, and intercity rail, with high-speed rail networks under development in several regions. Most public transport services operate along fixed corridors with designated boarding points and published timetables, allowing for predictable operations and efficient use of infrastructure. High-frequency services often prioritize regular headways over exact departure times. However, many trips involve multimodal travel, such as walking or feeder bus services to access rail stations, highlighting the importance of network coordination and cost-effective planning.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-INF007', 'D', ARRAY['D']::TEXT[], 'The passage describes multimodal trips and the importance of network coordination, which implies planning must connect modes.', '{"C": "The text presents feeder buses as part of multimodal trips, not as a problem to remove.", "A": "The text stresses network coordination, which single-mode planning would undermine.", "B": "Transfer fares are not discussed, and raising them would not address coordination."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-TS007', 'HDSAT-RW-M18-TS007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Public transport (also known as public transportation, public transit, mass transit, or simply transit) refers to forms of transport made available for use by the general public. Public transport systems typically operate on fixed routes and schedules and charge a standardized fare intended to cover operating costs, often supplemented by public funding where required. There is no universally fixed definition of which modes are included. While systems such as buses and railways are commonly cited, air travel is often excluded from general discussions of public transport due to its market-driven structure and competitive pricing. Common examples include city buses, trolleybuses, trams (or light rail), rapid transit systems, passenger trains, and ferries. Intercity public transport is primarily provided by airlines, coaches, and intercity rail, with high-speed rail networks under development in several regions. Most public transport services operate along fixed corridors with designated boarding points and published timetables, allowing for predictable operations and efficient use of infrastructure. High-frequency services often prioritize regular headways over exact departure times. However, many trips involve multimodal travel, such as walking or feeder bus services to access rail stations, highlighting the importance of network coordination and cost-effective planning.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares the environmental effects of buses and airlines."}, {"id": "B", "text": "It defines public transport, discusses which modes are included, and describes how services are operated and connected."}, {"id": "C", "text": "It argues that public transport should be free of charge."}, {"id": "D", "text": "It traces the history of the first urban tram systems."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Public transport", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Public_transport', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-TS007', 'B', ARRAY['B']::TEXT[], 'The text moves from a definition and the question of scope to operational features and multimodal connections.', '{"A": "Environmental effects are not discussed.", "C": "Fares and funding are described, but free service is not proposed.", "D": "No historical development of trams is given."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CE007', 'HDSAT-RW-M18-CE007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Public transport (also known as public transportation, public transit, mass transit, or simply transit) refers to forms of transport made available for use by the general public. Public transport systems typically operate on fixed routes and schedules and charge a standardized fare intended to cover operating costs, often supplemented by public funding where required. There is no universally fixed definition of which modes are included. While systems such as buses and railways are commonly cited, air travel is often excluded from general discussions of public transport due to its market-driven structure and competitive pricing. Common examples include city buses, trolleybuses, trams (or light rail), rapid transit systems, passenger trains, and ferries. Intercity public transport is primarily provided by airlines, coaches, and intercity rail, with high-speed rail networks under development in several regions. Most public transport services operate along fixed corridors with designated boarding points and published timetables, allowing for predictable operations and efficient use of infrastructure. High-frequency services often prioritize regular headways over exact departure times. However, many trips involve multimodal travel, such as walking or feeder bus services to access rail stations, highlighting the importance of network coordination and cost-effective planning.', 'Which quotation from the text most directly supports the claim that air travel is often excluded from definitions of public transport?', '[{"id": "A", "text": "High-frequency services often prioritize regular headways over exact departure times."}, {"id": "B", "text": "Public transport systems typically operate on fixed routes and schedules and charge a standardized fare intended to cover operating costs, often supplemented by public funding where required."}, {"id": "C", "text": "While systems such as buses and railways are commonly cited, air travel is often excluded from general discussions of public transport due to its market-driven structure and competitive pricing."}, {"id": "D", "text": "Common examples include city buses, trolleybuses, trams (or light rail), rapid transit systems, passenger trains, and ferries."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Public transport", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Public_transport', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CE007', 'C', ARRAY['C']::TEXT[], 'The correct quotation states that air travel is often excluded and gives the market-driven reasons.', '{"B": "This sentence describes fares and funding, not which modes count.", "D": "This sentence lists examples but says nothing about air travel''s exclusion.", "A": "This sentence concerns scheduling frequency."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CI008', 'HDSAT-RW-M18-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Congestion pricing or congestion charges is a system of charging users of public goods that are subject to congestion through excess demand, such as through higher peak charges for use of bus services, electricity, metros, railways, telephones, and road pricing to reduce traffic congestion; airlines and shipping companies may be charged higher fees for slots at airports and through canals at busy times. This pricing strategy regulates demand, making it possible to manage congestion without increasing supply. According to the economic theory behind congestion pricing, the objective of this policy is to use the price mechanism to cover the social cost of an activity where users otherwise do not pay for the negative externalities they create (such as driving in a congested area during peak demand). By setting a price on an over-consumed product, congestion pricing encourages the redistribution of the demand in space or in time, leading to more efficient outcomes. Singapore was the first country to introduce congestion pricing on its urban roads in 1975, and was refined in 1998. Since then, it has been implemented in cities including London, Durham, England, Stockholm, Gothenburg, Milan, and New York City. In the United States, it was also considered in Washington, D.C., San Francisco, and Boston prior to the COVID-19 pandemic.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Congestion pricing charges users of congested goods to shift demand and reduce congestion without expanding supply."}, {"id": "B", "text": "Congestion pricing raises revenue by increasing the supply of roads and transit."}, {"id": "C", "text": "Congestion pricing was first introduced in London in 1975."}, {"id": "D", "text": "Congestion pricing applies only to road traffic and never to airports or canals."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Congestion pricing", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Congestion_pricing', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CI008', 'A', ARRAY['A']::TEXT[], 'The passage defines congestion pricing, explains the economic rationale of charging for negative externalities, and lists cities that have adopted it.', '{"B": "The text says the strategy manages congestion without increasing supply.", "C": "The text says Singapore was the first country to introduce it on urban roads in 1975.", "D": "The text says airlines and shipping companies may be charged higher fees for slots at airports and through canals."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-INF008', 'HDSAT-RW-M18-INF008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Congestion pricing or congestion charges is a system of charging users of public goods that are subject to congestion through excess demand, such as through higher peak charges for use of bus services, electricity, metros, railways, telephones, and road pricing to reduce traffic congestion; airlines and shipping companies may be charged higher fees for slots at airports and through canals at busy times. This pricing strategy regulates demand, making it possible to manage congestion without increasing supply. According to the economic theory behind congestion pricing, the objective of this policy is to use the price mechanism to cover the social cost of an activity where users otherwise do not pay for the negative externalities they create (such as driving in a congested area during peak demand). By setting a price on an over-consumed product, congestion pricing encourages the redistribution of the demand in space or in time, leading to more efficient outcomes. Singapore was the first country to introduce congestion pricing on its urban roads in 1975, and was refined in 1998. Since then, it has been implemented in cities including London, Durham, England, Stockholm, Gothenburg, Milan, and New York City. In the United States, it was also considered in Washington, D.C., San Francisco, and Boston prior to the COVID-19 pandemic.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-INF008', 'B', ARRAY['B']::TEXT[], 'The passage states that pricing encourages demand to shift in space or time, which corresponds to changing travel times or routes.', '{"A": "The text says the policy encourages redistribution of demand in space or time, which means fewer peak trips, not more.", "C": "The text presents pricing as a complement to managing demand, not a replacement for transit.", "D": "The text says the price covers the social cost of an activity; it does not claim all externalities disappear."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-TS008', 'HDSAT-RW-M18-TS008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Congestion pricing or congestion charges is a system of charging users of public goods that are subject to congestion through excess demand, such as through higher peak charges for use of bus services, electricity, metros, railways, telephones, and road pricing to reduce traffic congestion; airlines and shipping companies may be charged higher fees for slots at airports and through canals at busy times. This pricing strategy regulates demand, making it possible to manage congestion without increasing supply. According to the economic theory behind congestion pricing, the objective of this policy is to use the price mechanism to cover the social cost of an activity where users otherwise do not pay for the negative externalities they create (such as driving in a congested area during peak demand). By setting a price on an over-consumed product, congestion pricing encourages the redistribution of the demand in space or in time, leading to more efficient outcomes. Singapore was the first country to introduce congestion pricing on its urban roads in 1975, and was refined in 1998. Since then, it has been implemented in cities including London, Durham, England, Stockholm, Gothenburg, Milan, and New York City. In the United States, it was also considered in Washington, D.C., San Francisco, and Boston prior to the COVID-19 pandemic.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that congestion pricing has failed everywhere it has been tried."}, {"id": "B", "text": "It defines congestion pricing, explains its economic rationale, and gives its history and examples."}, {"id": "C", "text": "It compares the design of Singapore''s system with London''s in detail."}, {"id": "D", "text": "It explains how to calculate the social cost of a subway ride."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Congestion pricing", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Congestion_pricing', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-TS008', 'B', ARRAY['B']::TEXT[], 'The text defines the policy, explains the theory, and then lists Singapore, London and other adopters.', '{"A": "The text describes adoption in many cities without evaluating failure.", "C": "The cities are listed as examples, not compared in detail.", "D": "No calculation method is given."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CE008', 'HDSAT-RW-M18-CE008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Easy', 'multiple_choice', 'Congestion pricing or congestion charges is a system of charging users of public goods that are subject to congestion through excess demand, such as through higher peak charges for use of bus services, electricity, metros, railways, telephones, and road pricing to reduce traffic congestion; airlines and shipping companies may be charged higher fees for slots at airports and through canals at busy times. This pricing strategy regulates demand, making it possible to manage congestion without increasing supply. According to the economic theory behind congestion pricing, the objective of this policy is to use the price mechanism to cover the social cost of an activity where users otherwise do not pay for the negative externalities they create (such as driving in a congested area during peak demand). By setting a price on an over-consumed product, congestion pricing encourages the redistribution of the demand in space or in time, leading to more efficient outcomes. Singapore was the first country to introduce congestion pricing on its urban roads in 1975, and was refined in 1998. Since then, it has been implemented in cities including London, Durham, England, Stockholm, Gothenburg, Milan, and New York City. In the United States, it was also considered in Washington, D.C., San Francisco, and Boston prior to the COVID-19 pandemic.', 'Which quotation from the text most directly supports the claim that congestion pricing manages demand without adding capacity?', '[{"id": "A", "text": "This pricing strategy regulates demand, making it possible to manage congestion without increasing supply."}, {"id": "B", "text": "In the United States, it was also considered in Washington, D.C., San Francisco, and Boston prior to the COVID-19 pandemic."}, {"id": "C", "text": "According to the economic theory behind congestion pricing, the objective of this policy is to use the price mechanism to cover the social cost of an activity where users otherwise do not pay for the negative externalities they create."}, {"id": "D", "text": "Singapore was the first country to introduce congestion pricing on its urban roads in 1975, and was refined in 1998."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Congestion pricing", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Congestion_pricing', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CE008', 'A', ARRAY['A']::TEXT[], 'The correct quotation states directly that demand is regulated so congestion can be managed without increasing supply.', '{"D": "This sentence gives a historical first, not the demand-supply relationship.", "B": "This sentence lists cities that considered the policy.", "C": "This sentence explains the theoretical objective but does not mention supply."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CI009', 'HDSAT-RW-M18-CI009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Microfinance is the provision of financial services to individuals and small businesses, particularly those with low incomes and limited access to conventional banking and related financial services. It encompasses services such as microcredit, savings, checking accounts, microinsurance, and payment systems. Modern microfinance developed in the 1970s, particularly through the work of Muhammad Yunus and the Grameen Bank in Bangladesh, although its historical roots extend to earlier cooperative lending and savings initiatives in Europe. Originally associated with small loans to entrepreneurs lacking access to credit, microfinance later expanded to encompass a broader range of financial services and evolved into a wider approach to financial inclusion aimed at expanding access to financial services for underserved populations. Microfinance has been promoted as a means of reducing poverty, supporting economic development, fostering entrepreneurship, and improving households'' ability to manage financial risks. Its effectiveness and social impact remain subjects of debate, particularly regarding poverty reduction, borrower over-indebtedness, interest rates, financial sustainability, and its impact on women and low-income communities. ‘Microfinance’ now generally refers to a broad array of formal financial services tailored for poor and low-income individuals, and others marginalized from conventional financial systems.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Microfinance was invented in Europe in the 1970s by Muhammad Yunus."}, {"id": "B", "text": "Microfinance provides financial services to low-income people, has expanded beyond microcredit, and has effects that remain debated."}, {"id": "C", "text": "Microfinance consists only of small loans to entrepreneurs."}, {"id": "D", "text": "Microfinance has been proven to eliminate poverty wherever it is available."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Microfinance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Microfinance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CI009', 'B', ARRAY['B']::TEXT[], 'The passage defines microfinance broadly, traces its modern development, and notes the continuing debate over its impact.', '{"C": "The text says it encompasses microcredit, savings, checking, microinsurance and payment systems.", "A": "The text says modern microfinance developed in the 1970s through Yunus and the Grameen Bank in Bangladesh, though earlier roots were in Europe.", "D": "The text says its effectiveness and social impact remain subjects of debate."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-INF009', 'HDSAT-RW-M18-INF009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Microfinance is the provision of financial services to individuals and small businesses, particularly those with low incomes and limited access to conventional banking and related financial services. It encompasses services such as microcredit, savings, checking accounts, microinsurance, and payment systems. Modern microfinance developed in the 1970s, particularly through the work of Muhammad Yunus and the Grameen Bank in Bangladesh, although its historical roots extend to earlier cooperative lending and savings initiatives in Europe. Originally associated with small loans to entrepreneurs lacking access to credit, microfinance later expanded to encompass a broader range of financial services and evolved into a wider approach to financial inclusion aimed at expanding access to financial services for underserved populations. Microfinance has been promoted as a means of reducing poverty, supporting economic development, fostering entrepreneurship, and improving households'' ability to manage financial risks. Its effectiveness and social impact remain subjects of debate, particularly regarding poverty reduction, borrower over-indebtedness, interest rates, financial sustainability, and its impact on women and low-income communities. ‘Microfinance’ now generally refers to a broad array of formal financial services tailored for poor and low-income individuals, and others marginalized from conventional financial systems.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-INF009', 'C', ARRAY['C']::TEXT[], 'The passage explicitly distinguishes today''s broad array of services from the original association with small loans.', '{"A": "The text says microfinance originally referred to small loans but later expanded to a broader range of services.", "D": "The text says it targets individuals and small businesses with low incomes and limited access to conventional banking.", "B": "The text describes it as an evolving approach to financial inclusion, not an ended experiment."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-TS009', 'HDSAT-RW-M18-TS009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Microfinance is the provision of financial services to individuals and small businesses, particularly those with low incomes and limited access to conventional banking and related financial services. It encompasses services such as microcredit, savings, checking accounts, microinsurance, and payment systems. Modern microfinance developed in the 1970s, particularly through the work of Muhammad Yunus and the Grameen Bank in Bangladesh, although its historical roots extend to earlier cooperative lending and savings initiatives in Europe. Originally associated with small loans to entrepreneurs lacking access to credit, microfinance later expanded to encompass a broader range of financial services and evolved into a wider approach to financial inclusion aimed at expanding access to financial services for underserved populations. Microfinance has been promoted as a means of reducing poverty, supporting economic development, fostering entrepreneurship, and improving households'' ability to manage financial risks. Its effectiveness and social impact remain subjects of debate, particularly regarding poverty reduction, borrower over-indebtedness, interest rates, financial sustainability, and its impact on women and low-income communities. ‘Microfinance’ now generally refers to a broad array of formal financial services tailored for poor and low-income individuals, and others marginalized from conventional financial systems.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains how to apply for a microloan step by step."}, {"id": "B", "text": "It defines microfinance, traces its modern development, and describes its expansion and contested impact."}, {"id": "C", "text": "It compares interest rates charged by banks in Europe and Bangladesh."}, {"id": "D", "text": "It argues that microcredit should be abolished."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Microfinance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Microfinance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-TS009', 'B', ARRAY['B']::TEXT[], 'The text moves from definition to origins, then to the broadening of services and the debate over results.', '{"C": "Interest rates are mentioned only as a subject of debate, with no comparison.", "D": "The text reports debate without advocating abolition.", "A": "No application process is described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CE009', 'HDSAT-RW-M18-CE009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Microfinance is the provision of financial services to individuals and small businesses, particularly those with low incomes and limited access to conventional banking and related financial services. It encompasses services such as microcredit, savings, checking accounts, microinsurance, and payment systems. Modern microfinance developed in the 1970s, particularly through the work of Muhammad Yunus and the Grameen Bank in Bangladesh, although its historical roots extend to earlier cooperative lending and savings initiatives in Europe. Originally associated with small loans to entrepreneurs lacking access to credit, microfinance later expanded to encompass a broader range of financial services and evolved into a wider approach to financial inclusion aimed at expanding access to financial services for underserved populations. Microfinance has been promoted as a means of reducing poverty, supporting economic development, fostering entrepreneurship, and improving households'' ability to manage financial risks. Its effectiveness and social impact remain subjects of debate, particularly regarding poverty reduction, borrower over-indebtedness, interest rates, financial sustainability, and its impact on women and low-income communities. ‘Microfinance’ now generally refers to a broad array of formal financial services tailored for poor and low-income individuals, and others marginalized from conventional financial systems.', 'Which quotation from the text most directly supports the claim that microfinance has expanded beyond small loans?', '[{"id": "A", "text": "Its effectiveness and social impact remain subjects of debate."}, {"id": "B", "text": "Microfinance has been promoted as a means of reducing poverty, supporting economic development, fostering entrepreneurship, and improving households'' ability to manage financial risks."}, {"id": "C", "text": "Modern microfinance developed in the 1970s, particularly through the work of Muhammad Yunus and the Grameen Bank in Bangladesh."}, {"id": "D", "text": "It encompasses services such as microcredit, savings, checking accounts, microinsurance, and payment systems."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Microfinance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Microfinance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CE009', 'D', ARRAY['D']::TEXT[], 'Only the correct quotation lists the varied services that go beyond microcredit.', '{"C": "This sentence gives the modern origin of microfinance.", "B": "This sentence lists goals attributed to microfinance, not the range of services.", "A": "This sentence describes the debate over results."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CI010', 'HDSAT-RW-M18-CI010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The urban heat island (UHI) effect is a meteorological and climatological phenomenon in which urban areas experience significantly warmer temperatures than surrounding rural areas. The temperature difference is usually larger at night than during the day, and is most apparent when winds are weak, under block conditions, noticeably during the summer and winter. The main cause of the UHI effect is from the modification of land surfaces, while waste heat generated by energy usage is a secondary contributor. Urban areas occupy about 0.5% of the Earth''s land surface but host more than half of the world''s population. As a population center grows, it tends to expand its area and increase its average temperature. Another key term is heat island; the term can be used to refer to any area that is relatively hotter than the surroundings, but generally refers to human-disturbed areas. Monthly rainfall is greater downwind of cities, partially due to the UHI. Increases in heat within urban centers increase the length of growing seasons, decrease air quality by increasing the production of pollutants such as ozone, and decrease water quality as warmer waters flow into area streams and put stress on their ecosystems. Not all cities have a distinct urban heat island, and the heat island characteristics depend strongly on the background climate of the area where the city is located. The impact in a city can significantly change based on its local environment.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Urban heat islands are caused mainly by waste heat from energy use."}, {"id": "B", "text": "The urban heat island effect is strongest during the day and in strong winds."}, {"id": "C", "text": "Urban heat islands are warmer urban areas caused mainly by altered land surfaces, with effects on seasons, air quality and water."}, {"id": "D", "text": "Every city has a distinct urban heat island regardless of its climate."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Urban heat island", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Urban_heat_island', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CI010', 'C', ARRAY['C']::TEXT[], 'The passage defines the urban heat island effect, identifies its main cause, and lists consequences for growing seasons, air and water quality.', '{"A": "The text calls land-surface modification the main cause and waste heat a secondary contributor.", "B": "The text says the difference is usually larger at night and most apparent when winds are weak.", "D": "The text says not all cities have a distinct urban heat island and that characteristics depend on background climate."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-INF010', 'HDSAT-RW-M18-INF010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'The urban heat island (UHI) effect is a meteorological and climatological phenomenon in which urban areas experience significantly warmer temperatures than surrounding rural areas. The temperature difference is usually larger at night than during the day, and is most apparent when winds are weak, under block conditions, noticeably during the summer and winter. The main cause of the UHI effect is from the modification of land surfaces, while waste heat generated by energy usage is a secondary contributor. Urban areas occupy about 0.5% of the Earth''s land surface but host more than half of the world''s population. As a population center grows, it tends to expand its area and increase its average temperature. Another key term is heat island; the term can be used to refer to any area that is relatively hotter than the surroundings, but generally refers to human-disturbed areas. Monthly rainfall is greater downwind of cities, partially due to the UHI. Increases in heat within urban centers increase the length of growing seasons, decrease air quality by increasing the production of pollutants such as ozone, and decrease water quality as warmer waters flow into area streams and put stress on their ecosystems. Not all cities have a distinct urban heat island, and the heat island characteristics depend strongly on the background climate of the area where the city is located. The impact in a city can significantly change based on its local environment.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-INF010', 'B', ARRAY['B']::TEXT[], 'The stated conditions under which the effect is strongest imply that measurement should include calm nights rather than only daytime or windy periods.', '{"A": "The text says the effect is most apparent when winds are weak and larger at night, so midday with strong winds would understate it.", "D": "The text says the difference is noticeable during summer and winter, and it does not say the effect disappears in winter.", "C": "The text says heat island characteristics depend strongly on background climate."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-TS010', 'HDSAT-RW-M18-TS010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'The urban heat island (UHI) effect is a meteorological and climatological phenomenon in which urban areas experience significantly warmer temperatures than surrounding rural areas. The temperature difference is usually larger at night than during the day, and is most apparent when winds are weak, under block conditions, noticeably during the summer and winter. The main cause of the UHI effect is from the modification of land surfaces, while waste heat generated by energy usage is a secondary contributor. Urban areas occupy about 0.5% of the Earth''s land surface but host more than half of the world''s population. As a population center grows, it tends to expand its area and increase its average temperature. Another key term is heat island; the term can be used to refer to any area that is relatively hotter than the surroundings, but generally refers to human-disturbed areas. Monthly rainfall is greater downwind of cities, partially due to the UHI. Increases in heat within urban centers increase the length of growing seasons, decrease air quality by increasing the production of pollutants such as ozone, and decrease water quality as warmer waters flow into area streams and put stress on their ecosystems. Not all cities have a distinct urban heat island, and the heat island characteristics depend strongly on the background climate of the area where the city is located. The impact in a city can significantly change based on its local environment.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It traces the history of urban climatology from ancient Rome to the present."}, {"id": "B", "text": "It argues that cities should be abandoned because of rising temperatures."}, {"id": "C", "text": "It compares rainfall patterns in coastal and inland cities."}, {"id": "D", "text": "It defines the urban heat island effect, explains its causes, describes its consequences, and notes variation among cities."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Urban heat island", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Urban_heat_island', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-TS010', 'D', ARRAY['D']::TEXT[], 'The text moves from definition and timing, to causes and scale, to consequences, and finally to variation by local environment.', '{"A": "No history of the field is given.", "B": "The text describes effects without recommending abandonment.", "C": "Rainfall is mentioned once as an effect downwind of cities, with no comparison."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M18-CE010', 'HDSAT-RW-M18-CE010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The urban heat island (UHI) effect is a meteorological and climatological phenomenon in which urban areas experience significantly warmer temperatures than surrounding rural areas. The temperature difference is usually larger at night than during the day, and is most apparent when winds are weak, under block conditions, noticeably during the summer and winter. The main cause of the UHI effect is from the modification of land surfaces, while waste heat generated by energy usage is a secondary contributor. Urban areas occupy about 0.5% of the Earth''s land surface but host more than half of the world''s population. As a population center grows, it tends to expand its area and increase its average temperature. Another key term is heat island; the term can be used to refer to any area that is relatively hotter than the surroundings, but generally refers to human-disturbed areas. Monthly rainfall is greater downwind of cities, partially due to the UHI. Increases in heat within urban centers increase the length of growing seasons, decrease air quality by increasing the production of pollutants such as ozone, and decrease water quality as warmer waters flow into area streams and put stress on their ecosystems. Not all cities have a distinct urban heat island, and the heat island characteristics depend strongly on the background climate of the area where the city is located. The impact in a city can significantly change based on its local environment.', 'Which quotation from the text most directly supports the claim that urban heat islands can worsen air quality?', '[{"id": "A", "text": "The main cause of the UHI effect is from the modification of land surfaces, while waste heat generated by energy usage is a secondary contributor."}, {"id": "B", "text": "Increases in heat within urban centers increase the length of growing seasons, decrease air quality by increasing the production of pollutants such as ozone, and decrease water quality as warmer waters flow into area streams and put stress on their ecosystems."}, {"id": "C", "text": "Not all cities have a distinct urban heat island, and the heat island characteristics depend strongly on the background climate of the area where the city is located."}, {"id": "D", "text": "Urban areas occupy about 0.5% of the Earth''s land surface but host more than half of the world''s population."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Urban heat island", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Urban_heat_island', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M18-CE010', 'B', ARRAY['B']::TEXT[], 'The correct quotation states directly that heat decreases air quality by increasing pollutants such as ozone.', '{"A": "This sentence identifies causes of the effect, not its consequences.", "D": "This sentence gives area and population figures.", "C": "This sentence notes that the effect varies among cities."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
